import os
from xml.dom import minidom

base = "unpacked_quarterly"
print("=== FILES ===")
for root, dirs, files in os.walk(base):
    for f in files:
        p = os.path.join(root, f)
        print(p, os.path.getsize(p))

print("\n=== STYLES (paragraph styles present) ===")
styles_path = os.path.join(base, "word", "styles.xml")
if os.path.exists(styles_path):
    dom = minidom.parse(styles_path)
    for st in dom.getElementsByTagName("w:style"):
        if st.getAttribute("w:type") == "paragraph":
            sid = st.getAttribute("w:styleId")
            name = ""
            for n in st.getElementsByTagName("w:name"):
                name = n.getAttribute("w:val")
            print(sid, "->", name)

print("\n=== PARAGRAPHS IN document.xml ===")
doc_path = os.path.join(base, "word", "document.xml")
dom = minidom.parse(doc_path)
paras = dom.getElementsByTagName("w:p")
for i, p in enumerate(paras):
    style = ""
    pPr = p.getElementsByTagName("w:pPr")
    if pPr:
        ps = pPr[0].getElementsByTagName("w:pStyle")
        if ps:
            style = ps[0].getAttribute("w:val")
    # collect text
    texts = []
    for t in p.getElementsByTagName("w:t"):
        texts.append(t.firstChild.nodeValue if t.firstChild else "")
    txt = "".join(texts)
    # find runs and check run props (bold etc.) of first run
    runs = p.getElementsByTagName("w:r")
    rpr_info = []
    for r in runs[:3]:
        rpr = r.getElementsByTagName("w:rPr")
        flags = []
        if rpr:
            for child in rpr[0].childNodes:
                if child.nodeType == child.ELEMENT_NODE:
                    flags.append(child.nodeName)
        rtext = ""
        ts = r.getElementsByTagName("w:t")
        if ts and ts[0].firstChild:
            rtext = ts[0].firstChild.nodeValue
        rpr_info.append((rtext[:40], ",".join(flags)))
    print(f"[{i}] style='{style}' text='{txt[:100]}'")
    for ri in rpr_info:
        print("     run:", ri)

import xml.etree.ElementTree as ET

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
Q = "{%s}" % W
PATH = "unpacked/word/document.xml"

HEADLINES = {
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
}

ET.register_namespace(
    "ve", "http://schemas.openxmlformats.org/markup-compatibility/2006"
)
ET.register_namespace("o", "urn:schemas-microsoft-com:office:office")
ET.register_namespace(
    "r", "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
)
ET.register_namespace("v", "urn:schemas-microsoft-com:vml")
ET.register_namespace(
    "wp",
    "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing",
)
ET.register_namespace("w10", "urn:schemas-microsoft-com:office:word")
ET.register_namespace("w", W)

tree = ET.parse(PATH)
root = tree.getroot()


def para_text(para):
    parts = []
    for node in para.iter(Q + "t"):
        parts.append(node.text or "")
    return "".join(parts)


def add_underline_run_property(run):
    rpr = run.find(Q + "rPr")
    if rpr is None:
        rpr = ET.Element(Q + "rPr")
        run.insert(0, rpr)
    if rpr.find(Q + "u") is not None:
        return False
    u = ET.Element(Q + "u")
    u.set(Q + "val", "single")
    anchor = None
    for child in rpr:
        if child.tag in (Q + "rFonts", Q + "sz", Q + "szCs"):
            anchor = child
    if anchor is None:
        rpr.insert(0, u)
    else:
        rpr.insert(list(rpr).index(anchor) + 1, u)
    return True


count = 0
for para in root.iter(Q + "p"):
    if para_text(para).strip() in HEADLINES:
        for run in para.findall(Q + "r"):
            if add_underline_run_property(run):
                count += 1

assert count == len(HEADLINES), count

# verification pass on the updated tree
seen = set()
for para in root.iter(Q + "p"):
    text = para_text(para).strip()
    if text in HEADLINES:
        seen.add(text)
        for run in para.findall(Q + "r"):
            rpr = run.find(Q + "rPr")
            assert rpr is not None and rpr.find(Q + "u") is not None
            assert rpr.find(Q + "u").get(Q + "val") == "single"
assert seen == HEADLINES

tree.write(PATH, encoding="utf-8", xml_declaration=True)
print("Underlined %d headlines." % count)

import os
import sys

SKILL_ROOT = os.path.abspath(".codex/skills/docx")
sys.path.insert(0, SKILL_ROOT)

from scripts.document import Document

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

HEADLINES = {
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
}

doc = Document("unpacked")
editor = doc["word/document.xml"]
dom = editor.dom


def para_text(para):
    parts = []
    for t in para.getElementsByTagName("w:t"):
        if t.firstChild is not None:
            parts.append(t.firstChild.data)
    return "".join(parts)


def ensure_underline(run):
    rpr = None
    for child in run.childNodes:
        if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:rPr":
            rpr = child
            break
    if rpr is None:
        rpr = dom.createElement("w:rPr")
        run.insertBefore(rpr, run.firstChild)
    for child in rpr.childNodes:
        if (
            child.nodeType == child.ELEMENT_NODE
            and child.tagName == "w:u"
            and child.getAttribute("w:val") == "single"
        ):
            return False
    u = dom.createElement("w:u")
    u.setAttribute("w:val", "single")
    rpr.appendChild(u)
    return True


count = 0
paras = dom.getElementsByTagName("w:p")
for para in paras:
    if para_text(para).strip() in HEADLINES:
        for run in para.getElementsByTagName("w:r"):
            if ensure_underline(run):
                count += 1

assert count == len(HEADLINES), count

# verification pass over the in-memory document
seen = set()
for para in dom.getElementsByTagName("w:p"):
    text = para_text(para).strip()
    if text in HEADLINES:
        seen.add(text)
        runs = para.getElementsByTagName("w:r")
        assert runs.length > 0
        underlined = False
        for run in runs:
            for child in run.childNodes:
                if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:rPr":
                    for rpr_child in child.childNodes:
                        if (
                            rpr_child.nodeType == rpr_child.ELEMENT_NODE
                            and rpr_child.tagName == "w:u"
                            and rpr_child.getAttribute("w:val") == "single"
                        ):
                            underlined = True
        assert underlined, text
assert seen == HEADLINES

doc.save()
print("Underlined %d headlines." % count)

